typedef struct LinkList {
    int data;
    LinkList *next;
    LinkList *prev;
} LinkList, LinkNode;
bool ListInit(LinkList* &L) {
    L = new LinkNode;
    if (!L) return false;
    L->next = NULL;
    L->prev = NULL;
    L->data = -1;
    return true;
}

下面的 fiboA() 和 fiboB() 两个函数分别实现斐波那契数列，该数列第1、第2项值为1，其余各项分别为前两项之和。下面有关说法错误的是（　　）。
int fiboA(int n) {
    if (n == 0) return 1;
    if (n == 1) return 1;
    else return fiboA(n-1) + fiboA(n-2);
}
int fiboB(int n) {
    if ((n == 0) || (n == 1)) { fiboB[n] = n; return n; }
    else {
        if (fiboB[n] == 0) fiboB[n] = FiboB(n-1) + FiboB(n-2);
        return fiboB[n];
    }
}

